package mk.robol.compiler.pipeline;
import java.util.Collections;import org.junit.Test;import static org.junit.Assert.*;import mk.robol.compiler.ast.Ast.Program;import mk.robol.compiler.diagnostics.Diagnostic;
public class CompilerPipelineTest {
 @Test public void successfulPipelineProducesCode(){final Program p=new Program(Collections.emptyList(),null);CompilerPipeline c=new CompilerPipeline(s->new CompilerPipeline.Output<List<Token>>(Collections.<Token>emptyList(),Collections.<Diagnostic>emptyList()),t->new CompilerPipeline.Output<Program>(p,Collections.<Diagnostic>emptyList()),x->Collections.<Diagnostic>emptyList(),x->"go\nret");CompilationResult r=c.compile("source");assertTrue(r.isSuccessful());assertSame(p,r.getProgram());assertEquals("go\nret",r.getGeneratedCode());}
 @Test public void lexicalErrorsStopLaterPhases(){final int[] calls={0};Diagnostic e=new Diagnostic("LEX001","Unexpected character",Diagnostic.Severity.ERROR,null);CompilerPipeline c=new CompilerPipeline(s->new CompilerPipeline.Output<Token>(Collections.<Token>emptyList(),Collections.singletonList(e)),t->{calls[0]++;return new CompilerPipeline.Output<Program>(null,Collections.<Diagnostic>emptyList());},p->Collections.<Diagnostic>emptyList(),p->"bad");CompilationResult r=c.compile("@");assertTrue(r.hasErrors());assertNull(r.getGeneratedCode());assertEquals(0,calls[0]);}
 @Test public void semanticErrorsPreventGeneration(){final int[] calls={0};Program p=new Program(Collections.emptyList(),null);Diagnostic e=new Diagnostic("SEM001","Undeclared variable",Diagnostic.Severity.ERROR,null);CompilerPipeline c=new CompilerPipeline(s->new CompilerPipeline.Output<Token>(Collections.<Token>emptyList(),Collections.<Diagnostic>emptyList()),t->new CompilerPipeline.Output<Program>(p,Collections.<Diagnostic>emptyList()),x->Collections.singletonList(e),x->{calls[0]++;return "bad";});CompilationResult r=c.compile("source");assertTrue(r.hasErrors());assertNull(r.getGeneratedCode());assertEquals(0,calls[0]);}
}